SELECT gen_random_uuid()::text, 'formula', '$np = n_i^2$', 'Mass-Action Law', '$np = n_i^2;\qquad \text{n-type: } n \approx N_D,\ p = \frac{n_i^2}{N_D}$', NULL, 'In equilibrium the product of electron and hole concentrations is fixed by the material and temperature.', '[{"symbol":"$n, p$","meaning":"electron and hole concentrations","unit":"$\\text{cm}^{-3}$"},{"symbol":"$n_i$","meaning":"intrinsic concentration (Si ≈ 1.0 × 10¹⁰ at 300 K)","unit":"$\\text{cm}^{-3}$"},{"symbol":"$N_D$","meaning":"donor concentration","unit":"$\\text{cm}^{-3}$"}]'::jsonb, 'Doping raises the majority carriers and LOWERS the minority carriers by the same factor.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'semiconductors and pn junction' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
