SELECT gen_random_uuid()::text, 'formula', '$V_0 = V_T\ln\frac{N_AN_D}{n_i^2}$', 'Built-In Potential of a PN Junction', '$V_0 = V_T\ln\frac{N_AN_D}{n_i^2}$', '$\text{V}$', 'The barrier voltage across a junction with no bias.', '[{"symbol":"$V_T$","meaning":"thermal voltage, kT/q ≈ 25.9 mV at 300 K","unit":"$\\text{V}$"},{"symbol":"$N_A, N_D$","meaning":"acceptor and donor concentrations","unit":"$\\text{cm}^{-3}$"},{"symbol":"$n_i$","meaning":"intrinsic concentration","unit":"$\\text{cm}^{-3}$"}]'::jsonb, 'Silicon junctions give about 0.6 to 0.8 V; it rises only logarithmically with doping.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'semiconductors and pn junction' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE'
