SELECT gen_random_uuid()::text, 'formula', '$\sigma = q(n\mu_n + p\mu_p)$', 'Conductivity of a Semiconductor', '$\sigma = q(n\mu_n + p\mu_p),\qquad \rho = \frac{1}{\sigma}$', '$\text{S/m}$', 'How doping and mobility set a semiconductor''s conductivity.', '[{"symbol":"$q$","meaning":"electron charge","unit":"$\\text{C}$"},{"symbol":"$n, p$","meaning":"carrier concentrations","unit":"$\\text{m}^{-3}$"},{"symbol":"$\\mu_n, \\mu_p$","meaning":"electron and hole mobilities","unit":"$\\text{m}^2/\\text{V·s}$"}]'::jsonb, 'Electrons are about 3 times as mobile as holes in silicon, so n-type conducts better at the same doping.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'semiconductors and pn junction' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE'
