SELECT gen_random_uuid()::text, 'formula', '$r_d = \frac{nV_T}{I_D}$', 'Diode Dynamic Resistance', '$r_d = \frac{nV_T}{I_D} \approx \frac{26\ \text{mV}}{I_D}$', '$\Omega$', 'The small-signal resistance of a forward-biased diode at its operating point.', '[{"symbol":"$n$","meaning":"ideality factor (1 to 2)","unit":null},{"symbol":"$V_T$","meaning":"thermal voltage, kT/q ≈ 25.9 mV at 300 K","unit":"$\\text{V}$"},{"symbol":"$I_D$","meaning":"dc diode current","unit":"$\\text{A}$"}]'::jsonb, 'At 1 mA it is about 26 Ω; at 10 mA, 2.6 Ω. Use it for small ac signals only.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'diodes' AND s."active"), NULL, false, 'PENDING', now(), now()
