SELECT gen_random_uuid()::text, 'formula', '$\Delta V = nV_T\ln\frac{I_2}{I_1}$', 'Diode Voltage per Decade of Current', '$V_2 - V_1 = nV_T\ln\frac{I_2}{I_1} \approx 60n\ \text{mV per decade}$', '$\text{V}$', 'How much more forward voltage a diode needs for more current.', '[{"symbol":"$I_1, I_2$","meaning":"two forward currents","unit":"$\\text{A}$"},{"symbol":"$n$","meaning":"ideality factor","unit":null},{"symbol":"$V_T$","meaning":"thermal voltage, kT/q ≈ 25.9 mV at 300 K","unit":"$\\text{V}$"}]'::jsonb, 'Ten times the current costs only about 60 mV: why the 0.7 V model works.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'diodes' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE'
