SELECT gen_random_uuid()::text, 'formula', '$I = \frac{V_S - V_{D0}}{R}$', 'Diode Circuit with the Constant-Drop Model', '$I = \frac{V_S - V_{D0}}{R},\qquad V_{D0} \approx 0.7\ \text{V (Si)},\ 0.3\ \text{V (Ge)}$', '$\text{A}$', 'The quick solution of a diode circuit: replace a conducting diode with a fixed drop.', '[{"symbol":"$V_S$","meaning":"source voltage","unit":"$\\text{V}$"},{"symbol":"$V_{D0}$","meaning":"assumed diode drop","unit":"$\\text{V}$"},{"symbol":"$R$","meaning":"series resistance","unit":"$\\Omega$"}]'::jsonb, 'Check the assumption: if the answer gives negative current, the diode is off.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'diodes' AND s."active"), NULL, false, 'PENDING', now(), now()
