SELECT gen_random_uuid()::text, 'formula', '$\Delta V_D \approx -2\ \text{mV/°C} \times \Delta T$', 'Diode Voltage Temperature Coefficient', '$\Delta V_D \approx -2\ \text{mV/°C} \times \Delta T\quad (\text{constant current})$', '$\text{V}$', 'A silicon diode''s forward voltage falls about 2 mV for each degree of heating.', '[{"symbol":"$\\Delta T$","meaning":"temperature rise","unit":"$\\text{°C}$"}]'::jsonb, 'This is how diodes and transistor junctions serve as temperature sensors, and why bias drifts.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'diodes' AND s."active"), NULL, false, 'PENDING', now(), now()
