SELECT gen_random_uuid()::text, 'formula', '$\text{PIV}: V_m,\ 2V_m,\ V_m$', 'Peak Inverse Voltage of Rectifiers', '$\text{half-wave: } V_m\ (2V_m \text{ with a filter capacitor});\quad \text{center-tap: } 2V_m;\quad \text{bridge: } V_m$', '$\text{V}$', 'The largest reverse voltage each diode must block.', '[{"symbol":"$V_m$","meaning":"peak voltage applied to the rectifier","unit":"$\\text{V}$"}]'::jsonb, 'The center-tap needs diodes rated for twice the bridge''s; the bridge loses two diode drops (1.4 V) instead of one.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'rectifiers and filters' AND s."active"), NULL, false, 'PENDING', now(), now()
