SELECT gen_random_uuid()::text, 'formula', '$V_{r(pp)} \approx \frac{I_{dc}}{fC}$', 'Capacitor-Filter Ripple', '$V_{r(pp)} \approx \frac{I_{dc}}{f_rC},\qquad V_{dc} \approx V_m - \frac{V_{r(pp)}}{2},\qquad V_{r(rms)} \approx \frac{V_{r(pp)}}{2\sqrt3}$', '$\text{V}$', 'The peak-to-peak ripple left by a reservoir capacitor.', '[{"symbol":"$I_{dc}$","meaning":"load current","unit":"$\\text{A}$"},{"symbol":"$f_r$","meaning":"ripple frequency: line f half-wave, 2f full-wave","unit":"$\\text{Hz}$"},{"symbol":"$C$","meaning":"filter capacitance","unit":"$\\text{F}$"}]'::jsonb, 'Full-wave halves the ripple for the same capacitor because the ripple frequency doubles.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'rectifiers and filters' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE'
