SELECT gen_random_uuid()::text, 'formula', '$r = \frac{V_{r(rms)}}{V_{dc}}$', 'Ripple Factor', '$r = \frac{V_{r(rms)}}{V_{dc}} = \sqrt{\left(\frac{V_{rms}}{V_{dc}}\right)^2 - 1};\qquad \text{unfiltered: } 1.21 \text{ (half)},\ 0.483 \text{ (full)}$', NULL, 'How much ac rides on a rectifier''s dc output, as a fraction.', '[{"symbol":"$V_{r(rms)}$","meaning":"RMS of the ac (ripple) part","unit":"$\\text{V}$"},{"symbol":"$V_{dc}$","meaning":"average output","unit":"$\\text{V}$"},{"symbol":"$V_{rms}$","meaning":"total RMS output: V_m/2 half-wave, V_m/√2 full-wave","unit":"$\\text{V}$"}]'::jsonb, 'An unfiltered half-wave output has more ripple RMS than dc: r is over 1.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'rectifiers and filters' AND s."active"), NULL, true, 'PENDING', now(), now()
