SELECT gen_random_uuid()::text, 'formula', '$\eta = \frac{P_{dc}}{P_{ac}}$', 'Rectification Efficiency', '$\eta = \frac{V_{dc}^2/R}{V_{rms}^2/R}:\ \frac{4}{\pi^2} = 40.5\%\ (\text{half}),\quad \frac{8}{\pi^2} = 81.1\%\ (\text{full})$', NULL, 'The share of a rectifier''s output power that is useful dc, ideal diodes and resistive load.', '[{"symbol":"$P_{dc}$","meaning":"dc output power","unit":"$\\text{W}$"},{"symbol":"$P_{ac}$","meaning":"total output power (RMS)","unit":"$\\text{W}$"}]'::jsonb, 'Often quoted as 40.6% and 81.2%; full-wave is exactly twice half-wave.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'rectifiers and filters' AND s."active"), NULL, true, 'PENDING', now(), now()
