SELECT gen_random_uuid()::text, 'formula', '$I_Z = \frac{V_{in} - V_Z}{R_S} - I_L$', 'Zener Regulator Series Resistor', '$I_Z = \frac{V_{in} - V_Z}{R_S} - I_L,\qquad R_{S(\max)} = \frac{V_{in(\min)} - V_Z}{I_{Z(\min)} + I_{L(\max)}}$', '$\text{A}$', 'The current left for the Zener after the load takes its share, and the largest series resistor that keeps it regulating.', '[{"symbol":"$V_{in}$","meaning":"unregulated input","unit":"$\\text{V}$"},{"symbol":"$V_Z$","meaning":"Zener voltage","unit":"$\\text{V}$"},{"symbol":"$R_S$","meaning":"series resistor","unit":"$\\Omega$"},{"symbol":"$I_L$","meaning":"load current","unit":"$\\text{A}$"}]'::jsonb, 'Design at the worst case: lowest input with the heaviest load. Check the Zener''s power at highest input with no load.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'zener regulators' AND s."active"), NULL, false, 'PENDING', now(), now()
