SELECT gen_random_uuid()::text, 'formula', '$P_Z = V_ZI_Z$', 'Zener Power Dissipation', '$P_Z = V_ZI_Z,\qquad P_{Z(\max)} = V_Z\left(\frac{V_{in(\max)} - V_Z}{R_S}\right)\ (\text{no load})$', '$\text{W}$', 'The power the Zener must handle, worst when the load is removed at the highest input.', '[{"symbol":"$V_Z$","meaning":"Zener voltage","unit":"$\\text{V}$"},{"symbol":"$I_Z$","meaning":"Zener current","unit":"$\\text{A}$"}]'::jsonb, 'With no load, every milliampere through R_S goes through the Zener.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'zener regulators' AND s."active"), NULL, false, 'PENDING', now(), now()
