SELECT gen_random_uuid()::text, 'formula', '$I_B = \frac{V_{CC} - V_{BE}}{R_B + (\beta + 1)R_E}$', 'Base Bias with Emitter Resistor', '$I_B = \frac{V_{CC} - V_{BE}}{R_B + (\beta + 1)R_E},\quad I_C = \beta I_B,\quad V_{CE} = V_{CC} - I_CR_C - I_ER_E$', '$\text{A}$', 'The Q-point of a base-biased transistor; R_E = 0 is plain fixed bias.', '[{"symbol":"$V_{CC}$","meaning":"supply voltage","unit":"$\\text{V}$"},{"symbol":"$V_{BE}$","meaning":"base-emitter drop, about 0.7 V","unit":"$\\text{V}$"},{"symbol":"$R_B, R_C, R_E$","meaning":"base, collector and emitter resistors","unit":"$\\Omega$"},{"symbol":"$\\beta$","meaning":"common-emitter current gain","unit":null}]'::jsonb, 'R_E appears in the base loop multiplied by (β + 1): that is what steadies the Q-point against β.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'bjt biasing' AND s."active"), NULL, false, 'PENDING', now(), now()
