SELECT gen_random_uuid()::text, 'formula', '$I_E = \frac{V_{TH} - V_{BE}}{R_E + R_{TH}/(\beta + 1)}$', 'Voltage-Divider Bias', '$V_{TH} = V_{CC}\frac{R_2}{R_1 + R_2},\quad R_{TH} = R_1 \| R_2,\quad I_E = \frac{V_{TH} - V_{BE}}{R_E + R_{TH}/(\beta + 1)}$', '$\text{A}$', 'The Q-point of the most common bias circuit, from the Thévenin equivalent of the divider.', '[{"symbol":"$V_{CC}$","meaning":"supply voltage","unit":"$\\text{V}$"},{"symbol":"$R_1, R_2$","meaning":"upper and lower divider resistors","unit":"$\\Omega$"},{"symbol":"$R_E$","meaning":"emitter resistor","unit":"$\\Omega$"},{"symbol":"$\\beta$","meaning":"common-emitter current gain","unit":null}]'::jsonb, 'If βR_E ≥ 10R₂ the approximate method (V_B = V_TH, I_E = (V_B − 0.7)/R_E) is close enough.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'bjt biasing' AND s."active"), NULL, false, 'PENDING', now(), now()
