SELECT gen_random_uuid()::text, 'formula', '$V_{CE} = V_{CC} - I_C(R_C + R_E)$', 'DC Load Line', '$V_{CE} = V_{CC} - I_C(R_C + R_E);\qquad I_{C(sat)} = \frac{V_{CC}}{R_C + R_E},\ V_{CE(off)} = V_{CC}$', '$\text{V}$', 'Every dc operating point the circuit allows; the bias picks one Q-point on it.', '[{"symbol":"$V_{CC}$","meaning":"supply voltage","unit":"$\\text{V}$"},{"symbol":"$R_C, R_E$","meaning":"collector and emitter resistors","unit":"$\\Omega$"},{"symbol":"$I_C$","meaning":"collector current (≈ I_E)","unit":"$\\text{A}$"}]'::jsonb, 'For the largest undistorted swing, put the Q-point near the middle of the ac load line.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'bjt biasing' AND s."active"), NULL, false, 'PENDING', now(), now()
