SELECT gen_random_uuid()::text, 'formula', '$g_m = \frac{I_C}{V_T},\ r_e = \frac{V_T}{I_E}$', 'BJT Small-Signal Parameters', '$g_m = \frac{I_C}{V_T},\qquad r_\pi = \frac{\beta}{g_m} = (\beta + 1)r_e,\qquad r_e = \frac{V_T}{I_E}$', '$\text{S}$', 'The small-signal model values, all set by the dc bias current.', '[{"symbol":"$I_C, I_E$","meaning":"dc collector and emitter currents","unit":"$\\text{A}$"},{"symbol":"$V_T$","meaning":"thermal voltage, kT/q ≈ 25.9 mV at 300 K","unit":"$\\text{V}$"},{"symbol":"$\\beta$","meaning":"common-emitter current gain","unit":null}]'::jsonb, 'At I_C = 1 mA: g_m = 38.5 mS and r_e ≈ 26 Ω. Double the current, double g_m.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'bjt amplifiers' AND s."active"), NULL, false, 'PENDING', now(), now()
