SELECT gen_random_uuid()::text, 'formula', '$A_v = -\frac{R_C \| R_L}{r_e + R_E}$', 'Common-Emitter Amplifier', '$A_v = -\frac{R_C \| R_L}{r_e + R_E},\qquad R_{in} = R_1 \| R_2 \| (\beta + 1)(r_e + R_E),\qquad R_o \approx R_C$', NULL, 'Voltage gain, input and output resistance of the CE stage: high gain, inverted.', '[{"symbol":"$R_C, R_L$","meaning":"collector resistor and load","unit":"$\\Omega$"},{"symbol":"$r_e$","meaning":"emitter resistance, V_T/I_E","unit":"$\\Omega$"},{"symbol":"$R_E$","meaning":"unbypassed emitter resistance (0 if fully bypassed)","unit":"$\\Omega$"},{"symbol":"$\\beta$","meaning":"common-emitter current gain","unit":null}]'::jsonb, 'Bypassing R_E raises the gain to −(R_C‖R_L)/r_e but makes it depend on the bias current.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'bjt amplifiers' AND s."active"), NULL, true, 'PENDING', now(), now()
