SELECT gen_random_uuid()::text, 'formula', '$A_v = \frac{R_E''}{r_e + R_E''} \approx 1$', 'Emitter Follower (Common Collector)', '$A_v = \frac{R_E''}{r_e + R_E''},\quad R_{in} = R_B \| (\beta + 1)(r_e + R_E''),\quad R_o = R_E \| \left(r_e + \frac{R_s \| R_B}{\beta + 1}\right)$', NULL, 'A buffer: gain just under 1, high input resistance, low output resistance.', '[{"symbol":"$R_E''$","meaning":"R_E ‖ R_L","unit":"$\\Omega$"},{"symbol":"$r_e$","meaning":"emitter resistance, V_T/I_E","unit":"$\\Omega$"},{"symbol":"$\\beta$","meaning":"common-emitter current gain","unit":null},{"symbol":"$R_s$","meaning":"source resistance","unit":"$\\Omega$"}]'::jsonb, 'It gives current and power gain, not voltage gain; the output follows the input in phase.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'bjt amplifiers' AND s."active"), NULL, true, 'PENDING', now(), now()
