SELECT gen_random_uuid()::text, 'formula', '$A_v = \frac{R_C \| R_L}{r_e}$', 'Common-Base Amplifier', '$A_v \approx \frac{R_C \| R_L}{r_e},\qquad R_{in} = R_E \| r_e,\qquad A_i \approx \alpha < 1$', NULL, 'High voltage gain in phase, very low input resistance, current gain just under 1.', '[{"symbol":"$R_C, R_L$","meaning":"collector resistor and load","unit":"$\\Omega$"},{"symbol":"$r_e$","meaning":"emitter resistance, V_T/I_E","unit":"$\\Omega$"}]'::jsonb, 'Used at high frequencies because it has no Miller multiplication of C_μ.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'bjt amplifiers' AND s."active"), NULL, true, 'PENDING', now(), now()
