SELECT gen_random_uuid()::text, 'formula', '$I_D = k(V_{GS} - V_{th})^2$', 'MOSFET Drain Current', '$\text{saturation } (V_{DS} \ge V_{GS} - V_{th}): I_D = k(V_{GS} - V_{th})^2;\quad \text{triode: } I_D = k[2(V_{GS} - V_{th})V_{DS} - V_{DS}^2]$', '$\text{A}$', 'The square law of an enhancement MOSFET, and the triode region below it.', '[{"symbol":"$k$","meaning":"device constant (½k′W/L in some texts)","unit":"$\\text{A/V}^2$"},{"symbol":"$V_{GS}$","meaning":"gate-source voltage","unit":"$\\text{V}$"},{"symbol":"$V_{th}$","meaning":"threshold voltage","unit":"$\\text{V}$"},{"symbol":"$V_{DS}$","meaning":"drain-source voltage","unit":"$\\text{V}$"}]'::jsonb, 'No current below threshold. The two regions meet at V_DS = V_GS − V_th, where both formulas agree.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'fets and mosfets' AND s."active"), NULL, false, 'PENDING', now(), now()
