SELECT gen_random_uuid()::text, 'formula', '$g_m = 2\sqrt{kI_D}$', 'FET Transconductance', '$\text{JFET: } g_m = \frac{2I_{DSS}}{|V_P|}\left(1 - \frac{V_{GS}}{V_P}\right);\qquad \text{MOSFET: } g_m = 2k(V_{GS} - V_{th}) = 2\sqrt{kI_D}$', '$\text{S}$', 'How much drain current changes per volt of gate voltage at the Q-point.', '[{"symbol":"$I_{DSS}$","meaning":"JFET current at V_GS = 0","unit":"$\\text{A}$"},{"symbol":"$V_P$","meaning":"pinch-off voltage","unit":"$\\text{V}$"},{"symbol":"$k$","meaning":"MOSFET constant","unit":"$\\text{A/V}^2$"},{"symbol":"$I_D$","meaning":"drain current","unit":"$\\text{A}$"}]'::jsonb, 'FET g_m grows only with √I_D; a BJT''s grows with I_C, so BJTs give more gain per milliampere.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'fets and mosfets' AND s."active"), NULL, false, 'PENDING', now(), now()
