SELECT gen_random_uuid()::text, 'formula', '$A_v = -g_m(r_d \| R_D \| R_L)$', 'Common-Source Amplifier', '$\text{CS: } A_v = -g_m(r_d \| R_D \| R_L);\qquad \text{source follower: } A_v = \frac{g_mR_S''}{1 + g_mR_S''}$', NULL, 'The FET stages: common source inverts with gain; the source follower buffers.', '[{"symbol":"$g_m$","meaning":"transconductance","unit":"$\\text{S}$"},{"symbol":"$r_d$","meaning":"drain resistance (often ∞)","unit":"$\\Omega$"},{"symbol":"$R_D, R_L$","meaning":"drain resistor and load","unit":"$\\Omega$"},{"symbol":"$R_S''$","meaning":"R_S ‖ R_L","unit":"$\\Omega$"}]'::jsonb, 'An unbypassed source resistor R_S cuts CS gain to −g_mR_D′/(1 + g_mR_S).', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'fets and mosfets' AND s."active"), NULL, true, 'PENDING', now(), now()
