SELECT gen_random_uuid()::text, 'formula', '$V_{GS} = -I_DR_S$', 'JFET Self-Bias', '$V_{GS} = -I_DR_S,\qquad I_D = I_{DSS}\left(1 - \frac{V_{GS}}{V_P}\right)^2$', '$\text{V}$', 'A source resistor biases a JFET with one supply: solve the bias line with Shockley''s equation.', '[{"symbol":"$R_S$","meaning":"source resistor","unit":"$\\Omega$"},{"symbol":"$I_D$","meaning":"drain current","unit":"$\\text{A}$"},{"symbol":"$I_{DSS}, V_P$","meaning":"JFET parameters","unit":null}]'::jsonb, 'The quadratic gives two roots; keep the one with V_GS between V_P and 0.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'fets and mosfets' AND s."active"), NULL, false, 'PENDING', now(), now()
