SELECT gen_random_uuid()::text, 'formula', '$A_{dB} = 20\log_{10}|A_v|$', 'Voltage Gain in Decibels', '$A_{dB} = 20\log_{10}|A_v| = 10\log_{10}\frac{P_o}{P_i}\ (\text{equal resistances})$', NULL, 'Gain on a log scale: cascaded stages add in decibels.', '[{"symbol":"$A_v$","meaning":"voltage gain","unit":null},{"symbol":"$P_o, P_i$","meaning":"output and input power","unit":"$\\text{W}$"}]'::jsonb, 'Half power is −3 dB; half voltage is −6 dB. ×10 in voltage is +20 dB.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'frequency response' AND s."active"), NULL, true, 'PENDING', now(), now()
