SELECT gen_random_uuid()::text, 'formula', '$f_L = \frac{1}{2\pi(R_s + R_{in})C_C}$', 'Low-Frequency Cutoff of a Coupling Capacitor', '$f_L = \frac{1}{2\pi R_{eq}C};\quad R_{eq} = R_s + R_{in} \text{ (input)},\ R_o + R_L \text{ (output)},\ R_E \| \left(r_e + \frac{R_s''}{\beta}\right) \text{ (bypass)}$', '$\text{Hz}$', 'Each coupling or bypass capacitor makes a low-frequency corner at 1/(2πRC).', '[{"symbol":"$R_{eq}$","meaning":"resistance the capacitor sees","unit":"$\\Omega$"},{"symbol":"$C$","meaning":"coupling or bypass capacitor","unit":"$\\text{F}$"}]'::jsonb, 'The bypass capacitor sees a tiny resistance, so it usually sets the highest (dominant) f_L.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'frequency response' AND s."active"), NULL, false, 'PENDING', now(), now()
