SELECT gen_random_uuid()::text, 'formula', '$C_M = C_f(1 - A_v)$', 'Miller Effect', '$C_{M,in} = C_f(1 - A_v) = C_f(1 + |A_v|),\qquad f_H = \frac{1}{2\pi R_{th}C_{in}}$', '$\text{F}$', 'A small feedback capacitance looks (1 + |A_v|) times larger at the input of an inverting stage.', '[{"symbol":"$C_f$","meaning":"capacitance from output to input (C_μ or C_gd)","unit":"$\\text{F}$"},{"symbol":"$A_v$","meaning":"inverting gain across it","unit":null},{"symbol":"$R_{th}$","meaning":"resistance driving the input","unit":"$\\Omega$"}]'::jsonb, 'This is what limits a CE stage''s high-frequency response; the CB and cascode avoid it.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'frequency response' AND s."active"), NULL, false, 'PENDING', now(), now()
