SELECT gen_random_uuid()::text, 'formula', '$\text{GBW} = A_{CL}\,f_{CL}$', 'Gain-Bandwidth Product', '$\text{GBW} = A_{OL}f_c = f_T = A_{CL}f_{CL},\qquad f_{CL} = \frac{f_T}{1 + R_f/R_i}$', '$\text{Hz}$', 'For a single-pole amplifier, gain times bandwidth is constant.', '[{"symbol":"$f_T$","meaning":"unity-gain frequency","unit":"$\\text{Hz}$"},{"symbol":"$A_{CL}$","meaning":"closed-loop (noise) gain","unit":null},{"symbol":"$f_{CL}$","meaning":"closed-loop bandwidth","unit":"$\\text{Hz}$"}]'::jsonb, 'A 1 MHz op-amp at a gain of 100 has 10 kHz bandwidth. Use the non-inverting gain 1 + R_f/R_i even for an inverting stage.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'frequency response' AND s."active"), NULL, false, 'PENDING', now(), now()
