SELECT gen_random_uuid()::text, 'formula', '$f_H^* = f_H\sqrt{2^{1/n} - 1}$', 'Bandwidth of Cascaded Identical Stages', '$f_H^* = f_H\sqrt{2^{1/n} - 1},\qquad f_L^* = \frac{f_L}{\sqrt{2^{1/n} - 1}}$', '$\text{Hz}$', 'Cascading stages multiplies the gain but narrows the bandwidth.', '[{"symbol":"$n$","meaning":"number of identical stages","unit":null},{"symbol":"$f_H, f_L$","meaning":"one stage''s cutoffs","unit":"$\\text{Hz}$"}]'::jsonb, 'Two stages: the upper cutoff falls to 0.644 f_H. Gains multiply (dB add) using each stage''s LOADED gain.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'multistage and feedback amplifiers' AND s."active"), NULL, false, 'PENDING', now(), now()
