SELECT gen_random_uuid()::text, 'formula', '$A_f = \frac{A}{1 + A\beta}$', 'Gain with Negative Feedback', '$A_f = \frac{A}{1 + A\beta};\qquad BW_f = BW(1 + A\beta);\qquad \text{series-shunt: } R_{if} = R_i(1 + A\beta),\ R_{of} = \frac{R_o}{1 + A\beta}$', NULL, 'Feedback trades gain for stability, bandwidth, lower distortion and better impedances.', '[{"symbol":"$A$","meaning":"open-loop gain","unit":null},{"symbol":"$\\beta$","meaning":"feedback fraction","unit":null},{"symbol":"$1 + A\\beta$","meaning":"amount of feedback (desensitivity)","unit":null}]'::jsonb, 'When Aβ ≫ 1, A_f ≈ 1/β: the gain depends only on the feedback network.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'multistage and feedback amplifiers' AND s."active"), NULL, true, 'PENDING', now(), now()
