SELECT gen_random_uuid()::text, 'formula', '$v_o = -\frac{1}{RC}\int v_i\,dt$', 'Op-Amp Integrator and Differentiator', '$\text{integrator: } v_o = -\frac{1}{RC}\int v_i\,dt;\qquad \text{differentiator: } v_o = -RC\frac{dv_i}{dt}$', '$\text{V}$', 'Swapping a resistor for a capacitor makes the inverting amplifier integrate or differentiate.', '[{"symbol":"$R$","meaning":"input (integrator) or feedback (differentiator) resistor","unit":"$\\Omega$"},{"symbol":"$C$","meaning":"capacitor","unit":"$\\text{F}$"}]'::jsonb, 'A square wave into an integrator gives a triangle. Practical integrators add a large resistor across C.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'operational amplifiers' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
