SELECT gen_random_uuid()::text, 'formula', '$f_{\max} = \frac{SR}{2\pi V_p}$', 'Slew Rate and Full-Power Bandwidth', '$\frac{dv_o}{dt}\Big|_{\max} = 2\pi fV_p \le SR \implies f_{\max} = \frac{SR}{2\pi V_p}$', '$\text{Hz}$', 'The highest frequency an op-amp can deliver at full output swing without distortion.', '[{"symbol":"$SR$","meaning":"slew rate","unit":"$\\text{V/µs}$"},{"symbol":"$V_p$","meaning":"peak output voltage","unit":"$\\text{V}$"}]'::jsonb, 'Slew rate limits large signals; GBW limits small ones. Check both.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'operational amplifiers' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
