SELECT gen_random_uuid()::text, 'formula', '$\text{CMRR} = \frac{A_d}{A_{cm}}$', 'Common-Mode Rejection Ratio', '$\text{CMRR} = \frac{A_d}{A_{cm}},\qquad \text{CMRR}_{dB} = 20\log_{10}\frac{A_d}{A_{cm}};\qquad v_o = A_dv_d + A_{cm}v_{cm}$', NULL, 'How well an amplifier ignores a voltage common to both inputs.', '[{"symbol":"$A_d$","meaning":"differential gain","unit":null},{"symbol":"$A_{cm}$","meaning":"common-mode gain","unit":null},{"symbol":"$v_d, v_{cm}$","meaning":"difference and average of the inputs","unit":"$\\text{V}$"}]'::jsonb, 'v_cm is the AVERAGE of the two inputs, v_d their difference.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'operational amplifiers' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
