SELECT gen_random_uuid()::text, 'formula', '$V_{UT,LT} = \pm\beta V_{sat}$', 'Schmitt Trigger Thresholds', '$\beta = \frac{R_2}{R_1 + R_2}:\quad V_{UT} = +\beta V_{sat},\ V_{LT} = -\beta V_{sat},\quad V_H = 2\beta V_{sat}$', '$\text{V}$', 'An inverting comparator with positive feedback: two thresholds, so noise does not make it chatter.', '[{"symbol":"$R_2$","meaning":"resistor from + input to ground","unit":"$\\Omega$"},{"symbol":"$R_1$","meaning":"resistor from output to + input","unit":"$\\Omega$"},{"symbol":"$V_{sat}$","meaning":"output saturation voltage","unit":"$\\text{V}$"}]'::jsonb, 'The hysteresis width is 2βV_sat; it must exceed the noise on the input.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'operational amplifiers' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
