SELECT gen_random_uuid()::text, 'formula', '$A\beta = 1\angle 0°$', 'Barkhausen Criterion', '$|A\beta| = 1,\qquad \angle A\beta = 0° \text{ or } 360°$', NULL, 'The condition for sustained oscillation: unity loop gain with no net phase shift.', '[{"symbol":"$A$","meaning":"amplifier gain","unit":null},{"symbol":"$\\beta$","meaning":"feedback network gain","unit":null}]'::jsonb, 'To start, the loop gain must be slightly MORE than 1; it then settles to 1 as the amplitude limits.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'oscillators' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
