SELECT gen_random_uuid()::text, 'formula', '$f = \frac{1}{2\pi RC\sqrt6}$', 'RC Phase-Shift Oscillator', '$f = \frac{1}{2\pi RC\sqrt6},\qquad |A| \ge 29\quad (\text{three sections, C in series, R to ground})$', '$\text{Hz}$', 'Three RC sections give 180° of phase shift; an inverting amplifier gives the other 180°.', '[{"symbol":"$R$","meaning":"section resistance","unit":"$\\Omega$"},{"symbol":"$C$","meaning":"section capacitance","unit":"$\\text{F}$"}]'::jsonb, 'The network attenuates to 1/29 at that frequency, so the amplifier needs a gain of at least 29.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'oscillators' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
