SELECT gen_random_uuid()::text, 'formula', '$f = \frac{1}{2\pi RC}$', 'Wien-Bridge Oscillator', '$f = \frac{1}{2\pi RC},\qquad A = 3 \iff R_f = 2R_1$', '$\text{Hz}$', 'The low-distortion audio oscillator: the lead-lag network passes 1/3 with zero phase at f.', '[{"symbol":"$R$","meaning":"equal bridge resistors","unit":"$\\Omega$"},{"symbol":"$C$","meaning":"equal bridge capacitors","unit":"$\\text{F}$"}]'::jsonb, 'Its non-inverting amplifier needs a gain of exactly 3 (slightly more to start).', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'oscillators' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
