SELECT gen_random_uuid()::text, 'formula', '$f = \frac{1}{2\pi\sqrt{L_{eq}C_{eq}}}$', 'Colpitts and Hartley Oscillators', '$f = \frac{1}{2\pi\sqrt{L_{eq}C_{eq}}};\quad \text{Colpitts: } C_{eq} = \frac{C_1C_2}{C_1 + C_2};\quad \text{Hartley: } L_{eq} = L_1 + L_2 + 2M$', '$\text{Hz}$', 'LC oscillators for radio frequencies: the tank sets f, a tap feeds part of it back.', '[{"symbol":"$C_1, C_2$","meaning":"tapped capacitors (Colpitts)","unit":"$\\text{F}$"},{"symbol":"$L_1, L_2$","meaning":"tapped inductors (Hartley)","unit":"$\\text{H}$"},{"symbol":"$M$","meaning":"mutual inductance between them","unit":"$\\text{H}$"}]'::jsonb, 'Colpitts taps the capacitors (in series), Hartley the inductor. The feedback ratio is C₁/C₂ or L₂/L₁.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'oscillators' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
