SELECT gen_random_uuid()::text, 'formula', '$\eta = \frac{P_{o(ac)}}{P_{i(dc)}}$', 'Class A Efficiency', '$\eta = \frac{P_{o(ac)}}{P_{i(dc)}};\qquad \eta_{\max} = 25\%\ (\text{resistive load}),\ 50\%\ (\text{transformer-coupled})$', NULL, 'Class A conducts all the time, so it wastes most of its supply power as heat.', '[{"symbol":"$P_{o(ac)}$","meaning":"ac power to the load","unit":"$\\text{W}$"},{"symbol":"$P_{i(dc)}$","meaning":"dc power from the supply","unit":"$\\text{W}$"}]'::jsonb, 'A class A stage dissipates the MOST when there is no signal.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'power amplifiers' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
