SELECT gen_random_uuid()::text, 'formula', '$\eta = \frac{\pi}{4}\frac{V_p}{V_{CC}}$', 'Class B Push-Pull Efficiency', '$P_o = \frac{V_p^2}{2R_L},\quad P_{dc} = \frac{2V_{CC}V_p}{\pi R_L},\quad \eta = \frac{\pi}{4}\frac{V_p}{V_{CC}} \le 78.5\%$', NULL, 'Each transistor conducts half the cycle, so efficiency is far better than class A.', '[{"symbol":"$V_p$","meaning":"peak load voltage","unit":"$\\text{V}$"},{"symbol":"$V_{CC}$","meaning":"supply voltage","unit":"$\\text{V}$"},{"symbol":"$R_L$","meaning":"load resistance","unit":"$\\Omega$"}]'::jsonb, 'Crossover distortion near zero is why practical stages are class AB, biased just on.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'power amplifiers' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
