SELECT gen_random_uuid()::text, 'formula', '$P_{D(\max)} = \frac{2V_{CC}^2}{\pi^2R_L}$', 'Class B Maximum Transistor Dissipation', '$P_{D(\max)} = \frac{2V_{CC}^2}{\pi^2R_L}\ (\text{both transistors, at } V_p = \tfrac{2}{\pi}V_{CC}) \approx 0.4P_{o(\max)}$', '$\text{W}$', 'The worst-case heat in a class B stage, which happens at about 64% of full swing, not at full output.', '[{"symbol":"$V_{CC}$","meaning":"supply voltage","unit":"$\\text{V}$"},{"symbol":"$R_L$","meaning":"load resistance","unit":"$\\Omega$"}]'::jsonb, 'Each transistor dissipates half; size heat sinks for this, not for full output.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'power amplifiers' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
