SELECT gen_random_uuid()::text, 'formula', '$T_J = T_A + P_D(\theta_{JC} + \theta_{CS} + \theta_{SA})$', 'Heat Sink Thermal Resistance', '$T_J = T_A + P_D(\theta_{JC} + \theta_{CS} + \theta_{SA})$', '$\text{°C}$', 'Heat flows like current through thermal resistances in series: the temperature rise is power times their sum.', '[{"symbol":"$T_J, T_A$","meaning":"junction and ambient temperatures","unit":"$\\text{°C}$"},{"symbol":"$P_D$","meaning":"power dissipated","unit":"$\\text{W}$"},{"symbol":"$\\theta$","meaning":"thermal resistances: junction-case, case-sink, sink-air","unit":"$\\text{°C/W}$"}]'::jsonb, 'Solve for θ_SA to choose a heat sink that keeps T_J below its maximum.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE' AND s."normKey" = 'power amplifiers' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electronics 1 and 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
